  #define SAADC_CH_PSELN_PSELN_SELREF (0x10UL)       /*!< Selected reference, voltage determined by PADC_REFSEL                */


/* SAADC_CH_CONFIG: Input configuration for CH[n] */
  #define SAADC_CH_CONFIG_ResetValue (0x00020000UL)  /*!< Reset value of CONFIG register.                                      */

/* RESP @Bits 0..1 : Positive channel resistor control */
  #define SAADC_CH_CONFIG_RESP_Pos (0UL)             /*!< Position of RESP field.                                              */
